import { aws_cloudfront as cloudfront, aws_logs as logs } from 'aws-cdk-lib';

/**
 * お客様の基準値。基準はここにだけ書く。
 * 部品の既定値と、チェックシートのルールの閾値の両方がこの値を参照する。
 *
 * =====================================================================================
 * 【デモ3】お客様の基準が変わっても、直すのはこの1か所
 *
 * 今の困りごと
 *   ・商談中の2社目のチェーンでは「ログの保管は1年」。今の基準（6ヶ月）と違う。
 *   ・いまは基準が変わるたびに、9環境を1つずつ直して確かめている（4.5人日）。
 *
 * ここで見ていただくこと
 *   ・直すのは下の logRetention の1行だけ（SIX_MONTHS → ONE_YEAR）。
 *   ・この1行を、ログの作り方（部品の既定値）と、検査のルール（INF-07 の閾値）の両方が見ている。
 *     作るものと確かめるものが、同時に新しい基準に変わるので、ずれが起きない。
 *   ・直した部品は新しい版（v1.1.0）として公開され、各チームは取り込む前に PR で差分を確かめる。
 *     変わるのはログの保管期間（180日 → 365日）だけで、作り直しは起きない（PR #5）。
 *
 * これで解決すること
 *   ・基準の変更は 9環境ぶんで 4.5人日 → 約1人日。3社目の基準にも、ここ1か所で追従できる。
 *   ・顧客が増えても、インフラ担当を増やさずに回せる。
 * =====================================================================================
 */
export const POLICY = {
  /** INF-07 ログを定めた期間保管する ← 2社目の基準（1年）に合わせて、ここを ONE_YEAR にした（v1.1.0） */
  logRetention: logs.RetentionDays.ONE_YEAR,
  /** INF-21 外部との通信をTLSで暗号化する（入口の CloudFront が受け付ける最低の TLS） */
  minimumTls: cloudfront.SecurityPolicyProtocol.TLS_V1_2_2021,
  /** 入口の WAF：同じIPからのアクセスを、5分あたりこの回数までに抑える（クローラーやボットの連打を止める） */
  rateLimitPer5Min: 300,
  /** 共有DBのポート */
  databasePort: 5432,
} as const;

/** 部品が使うリージョン */
export const DEFAULT_REGION = 'ap-northeast-1';

/** CloudFront 用の証明書と WAF は、この リージョンにしか置けない */
export const EDGE_REGION = 'us-east-1';
